{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "A tocotrienol-rich fraction of palm oil, composed of lipophilic isoprenoid chromanols, has poor oral bioavailability in humans, directly supporting low F for the query's long-chain lipophilic ubiquinone.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Synthetic lycopene, a C40 isoprenoid, showed only about 1.2% systemic availability after an oral dose dispersed in oil, demonstrating that highly lipophilic isoprenoid molecules can have very low oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Phytoene, the closest structural analogue (Morgan 0.39), had an estimated absolute bioavailability of 58.5% in humans, providing evidence for high F in some long isoprenoids; however, phytoene is much smaller, acyclic, and lacks the quinone head, limiting transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C10"],
      "claim": "Hyperforin, a polyprenylated lipophilic natural product, showed high oral bioavailability in volunteers, suggesting that prenylated lipophilic molecules can be absorbed; its lower molecular weight and different scaffold reduce transfer to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C13"],
      "claim": "A controlled 13C-lycopene study reported 23.2% bioavailability for all-trans lycopene, above the 20% threshold, but this is at the high end of a wide lycopene range and is formulation/isomer-dependent.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted low. The query is an extremely lipophilic, high-MW ubiquinone with a long polyisoprenyl chain. The most transferable absorption-relevant evidence—tocotrienol poor bioavailability and low lycopene systemic availability—supports F < 20%. The high phytoene and hyperforin values are less transferable because of smaller size, different scaffolds, and absence of the quinone/polyisoprenyl combination.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for ubiquinone/CoQ9/CoQ10 in the provided evidence.",
    "The high phytoene bioavailability and variable lycopene data leave uncertainty about whether long isoprenoid lipophilicity alone dictates low F.",
    "Formulation effects are not captured; special formulations can improve absorption of lipophilic quinones."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

